// commerce.js — LE DOSSIER DE A À Z (13/10/2026, maquette validée par Ethan : « j'adore la maquette ; code ça en attendant »).
// Six étapes dans la fiche d'une affaire : 1 Dossier (DCE, consultation, tâches) · 2 Lecture des pièces (notes à plusieurs destinations, quantités repérées → chiffrage)
// · 3 Chiffrage (affaires.js, tableau V2B) · 4 Mémoire technique (plan selon les critères, blocs SCR réutilisés, variables du chiffrage) · 5 DPGF (le bordereau du client
// importé tel quel — .xlsx lu sans bibliothèque, ou collé depuis Excel — rempli depuis le prix de vente, écart, export) · 6 Offre (pièces à remettre, remise, gagnée / perdue, versions).
// Données : sur l'affaire (registre « affaire ») : consult, taches, quantites, memoire, dpgf, offre ; notes de lecture : n.dests[] (plusieurs destinations) ; blocs SCR = registre « doc » kind « bloc ».
import {regSet} from './reg.js';
import {affGet,affSet,affState,calcAffaire,DEST,DNS,BASE} from './affaires.js';
import {docsAll} from './docs.js';
import {prixBase,etudesOf,etudeFromRows,etudeAdd,chiffrageState} from './chiffrage.js';
import {zipEntries as zipEntriesX,inflate as inflateX,setCellsXml,rezip,colName} from './xlsx.js'; // 13/10 : réécrire les PU dans le .xlsx du client // 13/10 : chiffrage v2 — les quantités repérées préremplissent une zone (étude)
let A=null;export function initCommerce(api){A=api;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nb=(x,d)=>{x=+x||0;return x.toLocaleString('fr-FR',{maximumFractionDigits:d===undefined?0:d,minimumFractionDigits:d===undefined?0:d});};
const eur=x=>nb(x)+' €';const dFR=x=>x?new Date(x).toLocaleDateString('fr-FR'):'';const todayIso=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
const jours=(d1,d2)=>Math.round((new Date(d2+'T00:00:00')-new Date(d1+'T00:00:00'))/86400000);
const addD=(d,n)=>{const x=new Date(d+'T00:00:00');x.setDate(x.getDate()+n);return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0');};
export const STEPS=[['dossier','1 · Dossier'],['lecture','2 · Lecture'],['chiffrage','3 · Chiffrage'],['memoire','4 · Mémoire'],['dpgf','5 · DPGF'],['offre','6 · Offre']];
/* notes de lecture : plusieurs destinations (Ethan : « quand on surligne « série 2 imposée », mettre mémoire technique ET chiffrage ») — n.dests[] ; n.dest (ancien) reste lu */
export const noteDests=n=>Array.isArray(n.dests)&&n.dests.length?n.dests:(n.dest?[n.dest]:[]);
export const notesOf=(a,dest)=>(a.dce||[]).filter(d=>!d.deleted).flatMap(d=>(d.notes||[]).map((n,i)=>Object.assign({_doc:d.name,_docId:d.id,_i:i},n))).filter(n=>!dest||noteDests(n).includes(dest));
const noteDone=(n,dest)=>!!(n.done&&n.done[dest]);
export function notesBlock(a,dest,canEdit,titre){const N=notesOf(a,dest);if(!N.length)return '';const left=N.filter(n=>!noteDone(n,dest)).length;
  return `<div class="card soft cm-notes"><b style="font-size:12px">📌 ${titre||DEST[dest]} · ${N.length} note${N.length>1?'s':''} du DCE${left?` · <span style="color:#7a5200">${left} à prendre en compte</span>`:' · <span style="color:#15673a">toutes prises en compte</span>'}</b>
    ${N.map(n=>`<label class="cm-note${noteDone(n,dest)?' done':''}"><input type="checkbox" ${noteDone(n,dest)?'checked':''} ${canEdit?'':'disabled'} data-act="af" data-v="notedone|${esc(n._docId)}|${n._i}|${dest}"><span>${noteDests(n).includes('risque')?'⚠ ':''}<b>${esc(n.ref||'')}</b> ${n.extrait?'« '+esc(n.extrait)+' »':''}${n.texte?' — '+esc(n.texte):''} <span class="dim">(${esc(n._doc)}${noteDests(n).length>1?' · aussi '+noteDests(n).filter(x=>x!==dest).map(x=>DEST[x]||x).join(', '):''})</span></span></label>`).join('')}</div>`;}
/* ── état d'avancement des 6 étapes (pour les puces de la fiche) ── */
export function stepState(a){const C=calcAffaire(a);const pieces=(a.dce||[]).filter(d=>!d.deleted).length;const notes=notesOf(a).length;const q=a.quantites||{};const M=a.memoire||{};const secs=M.sections||[];const D=a.dpgf||{};const L=(D.lignes||[]).filter(l=>!l.section);const tot=L.reduce((s,l)=>s+(+l.pu||0)*(+l.qte||0),0);
  return {dossier:pieces>0&&!!a.dateReponse,lecture:notes>0||(q.rows||[]).length>0,chiffrage:C.total>0,memoire:secs.length>0&&secs.every(s=>s.etat==='pret'),dpgf:L.length>0&&Math.abs(tot-C.total)<1&&L.every(l=>+l.pu>0),offre:!!(a.offre&&a.offre.remiseAt),C,pieces,notes,L,tot};}
/* ═════════ 1 · DOSSIER ═════════ */
const TACHES=[['visite','Visite de site',a=>(a.consult||{}).visite?String(a.consult.visite).slice(0,10):null],['lecture','Lecture des pièces (CCTP, DPGF, plans)',a=>(a.consult||{}).questions?addD(a.consult.questions,-1):(a.dateReponse?addD(a.dateReponse,-6):null)],['questions','Questions au maître d\'œuvre',a=>(a.consult||{}).questions||null],['chiffrage','Chiffrage (v1 puis versions)',a=>a.dateReponse?addD(a.dateReponse,-4):null],['memoire','Mémoire technique',a=>a.dateReponse?addD(a.dateReponse,-2):null],['remise','DPGF + AE signés, dépôt de l\'offre',a=>a.dateReponse||null]];
export function dossierHTML(a,canEdit,ctx,dceBody){const c=a.consult||{};const ro=!canEdit;const st=stepState(a);const today=todayIso();const J=a.dateReponse?jours(today,a.dateReponse):null;const T=a.taches||{};
  const F=(k,l,type,extra,val)=>`<div><label class="f">${l}</label>${type==='select'?`<select class="f" data-afcs="${k}" ${ro?'disabled':''}>${extra}</select>`:`<input class="f" data-afcs="${k}" type="${type||'text'}" value="${esc(val!==undefined?val:(c[k]||''))}" ${ro?'disabled':''}${extra?' placeholder="'+esc(extra)+'"':''}>`}</div>`;
  return `<div class="ac-stats" style="margin-bottom:8px"><div class="ac-stat ${st.pieces?'ok':''}"><b>${st.pieces}</b><small>pièce${st.pieces>1?'s':''} au dossier</small></div><div class="ac-stat ${J===null?'':J<0?'bad':J<=3?'warn':''}"><b>${a.dateReponse?dFR(a.dateReponse):'—'}</b><small>remise de l'offre${J===null?'':J<0?' · dépassée':' · J-'+J}</small></div><div class="ac-stat"><b>${c.questions?dFR(c.questions):'—'}</b><small>limite des questions</small></div><div class="ac-stat"><b>${c.delai?esc(c.delai):'—'}</b><small>délai d'exécution</small></div><div class="ac-stat"><b>${Object.keys(T).filter(k=>T[k]).length} / ${TACHES.length}</b><small>tâches faites</small></div></div>
    <div class="card eq-form"><h3>La consultation <span class="hint">· lu dans le RC — à renseigner une fois, tout le dossier s'en sert</span></h3><div class="row af-grid">${F('moa','Maître d\'ouvrage','text','',a.moa||'')}${F('moe','Maître d\'œuvre / BE','text','',a.moe||'')}${F('procedure','Procédure','text','MAPA, appel d\'offres, gré à gré…')}${F('lot','Lot','text','ex. Lot 2 · réseau acier pré-isolé')}${F('variante','Variantes','select',['','autorisées','interdites','imposées'].map(v=>`<option value="${v}"${(c.variante||'')===v?' selected':''}>${v||'—'}</option>`).join(''))}${F('visite','Visite de site','datetime-local')}${F('questions','Date limite des questions','date')}${F('dateReponse','Remise de l\'offre','date','',a.dateReponse||'')}${F('remiseHeure','Heure limite','time')}${F('delai','Délai d\'exécution','text','ex. 22 semaines')}${F('criteres','Critères de jugement','text','ex. prix 60 % · valeur technique 40 %')}${F('plateforme','Plateforme de dépôt (lien)','url','https://…')}</div></div>
    <div class="card"><h3>Tâches <span class="hint">· posées depuis les dates de la consultation</span></h3><div class="cm-taches">${TACHES.map(([k,l,due])=>{const d=due(a);const late=d&&!T[k]&&d<today;return `<label class="cm-tache${T[k]?' done':''}${late?' late':''}"><input type="checkbox" ${T[k]?'checked':''} ${ro?'disabled':''} data-act="af" data-v="tache|${k}"><span><b>${l}</b>${d?`<small>${late?'⚠ en retard · ':''}pour le ${dFR(d)}</small>`:'<small>date : renseigne la consultation</small>'}</span></label>`;}).join('')}</div><div class="hint" style="margin-top:6px">Qui : chargé d'affaires <b>${esc(a.charge||'?')}</b> · conducteur pressenti <b>${esc(a.cdtx||'?')}</b> (onglet Fiche). La remise à J-3 et J-1 remonte dans « Aujourd'hui » du chargé d'affaires.</div></div>
    ${dceBody}`;}
/* ═════════ 2 · LECTURE ═════════ */
export function lectureHTML(a,canEdit,ctx){const docs=(a.dce||[]).filter(d=>!d.deleted);const N=notesOf(a);const q=Object.assign({rows:[]},a.quantites||{});const ro=!canEdit;const f=AS().lectDest||'';
  const byDest=k=>N.filter(n=>noteDests(n).includes(k));const shown=f?byDest(f):N;
  return `<div class="card"><h3>Pièces et notes de lecture <span class="hint">· ✎ sur une pièce = page / article, extrait, et pour qui : plusieurs destinations possibles</span></h3>
      ${docs.length?`<div class="cm-pieces">${docs.map(d=>`<div class="cm-piece"><span class="tx">${d.url?`<a href="${esc(d.url)}" target="_blank" rel="noopener">${esc(d.name)}</a>`:'<b>'+esc(d.name)+'</b>'}<small>${esc(d.cat||'')}${(d.notes||[]).length?' · '+(d.notes||[]).length+' note'+((d.notes||[]).length>1?'s':''):''}</small></span>${canEdit?`<button class="btn sm" data-act="af" data-v="dcenote|${esc(d.id)}">✎ Note</button>`:''}</div>`).join('')}</div>`:'<div class="eq-s">Aucune pièce : dépose le DCE à l\'étape 1 · Dossier.</div>'}
      <div class="eq-filtres" style="margin-top:8px"><button class="chip${f?'':' active'}" data-act="af" data-v="lectdest|">Toutes · ${N.length}</button>${Object.keys(DEST).map(k=>`<button class="chip${f===k?' active':''}" data-act="af" data-v="lectdest|${k}">${DEST[k]} · ${byDest(k).length}</button>`).join('')}</div>
      ${shown.length?shown.map(n=>`<div class="af-note cm-n"><span class="cm-tags">${noteDests(n).map(x=>`<span class="eq-tag ${x}">${DEST[x]||x}</span>`).join('')}</span> <b>${esc(n.ref||'')}</b>${n.extrait?` <i>« ${esc(n.extrait)} »</i>`:''}${n.texte?' — '+esc(n.texte):''}<span class="dim" style="font-size:11px"> · ${esc(n._doc)} · ${esc(n.by||'')}</span>${canEdit?` <button class="lnk" data-act="af" data-v="dcenoterm|${esc(n._docId)}|${n._i}" title="Retirer la note" style="color:#9b2c22">✕</button>`:''}</div>`).join(''):'<div class="eq-s" style="margin-top:6px">Pas encore de note de lecture.</div>'}
      <div class="hint" style="margin-top:6px">Les notes « chiffrage » et « risque » s'affichent en tête du chiffrage, « mémoire technique » en tête du mémoire, « question MOE » dans la liste des questions — chacune se coche quand elle est prise en compte.</div></div>`+quantitesHTML(a,canEdit);}
/* quantités repérées (DN × soudures × ml + compteurs) — 13/10 : carte à part, sous la lecture des pièces (dce.js) */
export function quantitesHTML(a,canEdit){const q=Object.assign({rows:[]},a.quantites||{});const ro=!canEdit;
  return `<div class="card"><h3>Quantités repérées <span class="hint">· DPGF, plans, profils, tracé — la source de chaque chiffre dans la note</span></h3>
      <div class="row af-grid">${[['ml','ml de tranchée','number'],['ss','sous-stations / raccordements','number'],['coudes','coudes','number'],['tes','tés','number'],['reductions','réductions','number'],['vannes','vannes','number']].map(([k,l,t])=>`<div><label class="f">${l}</label><input class="f" type="${t}" min="0" data-afq="${k}" value="${esc(q[k]??'')}" ${ro?'disabled':''}></div>`).join('')}</div>
      <div style="overflow:auto;margin-top:6px"><table class="rc af-tab"><tr><th>DN</th><th>Soudures</th><th>ml</th><th>Manchons</th><th>CND</th><th></th></tr>${(q.rows||[]).map((r,i)=>`<tr><td><select class="f af-dn" data-afqr="${i}|dn" ${ro?'disabled':''}>${DNS.map(d=>`<option value="${d}"${+r.dn===d?' selected':''}>DN ${d}</option>`).join('')}</select></td><td><input class="f af-n" type="number" min="0" data-afqr="${i}|soud" value="${esc(r.soud??'')}" ${ro?'disabled':''}></td><td><input class="f af-n" type="number" min="0" data-afqr="${i}|ml" value="${esc(r.ml??'')}" ${ro?'disabled':''}></td><td class="num">${nb(r.soud||0)}</td><td class="ch-flags"><label class="ch-sw${r.antenne?' on':''}" title="Antenne (contrôles)"><input type="checkbox" data-afqr="${i}|antenne" ${r.antenne?'checked':''} ${ro?'disabled':''}><i></i><span>ant.</span></label><label class="ch-sw${r.feeder?' on':''}" title="Feeder (contrôles)"><input type="checkbox" data-afqr="${i}|feeder" ${r.feeder?'checked':''} ${ro?'disabled':''}><i></i><span>feed.</span></label></td><td>${canEdit?`<button class="btn sm" data-act="af" data-v="qrm|${i}" style="color:#9b2c22">✕</button>`:''}</td></tr>`).join('')}${(q.rows||[]).length?`<tr class="tot"><td>Total</td><td class="num">${nb((q.rows||[]).reduce((s,r)=>s+(+r.soud||0),0))}</td><td class="num">${nb((q.rows||[]).reduce((s,r)=>s+(+r.ml||0),0))}</td><td class="num">${nb((q.rows||[]).reduce((s,r)=>s+(+r.soud||0),0))}</td><td colspan="2"></td></tr>`:''}</table></div>
      ${canEdit?`<div class="eq-acts" style="margin-top:8px"><button class="btn" data-act="af" data-v="qadd|">➕ DN</button><button class="btn primary" data-act="af" data-v="qprefill|" ${(q.rows||[]).length?'':'disabled'}>→ Préremplir le chiffrage</button><button class="btn" data-act="af" data-v="tab|sites">✎ Vérifier avec le tracé</button></div>`:''}
      <div class="hint" style="margin-top:6px">« Préremplir » crée (ou met à jour) la zone « Quantités repérées » du chiffrage avec ces DN : soudures et ml. Si le tracé donne autre chose que le DPGF, l'écart est signalé dans le chiffrage (source de la zone).</div></div>`;}
/* ═════════ 4 · MÉMOIRE TECHNIQUE ═════════ */
const PLAN_SCR=[['Présentation de SCR','pret'],['Compréhension du projet et contraintes du site','ecrire'],['Méthodologie de soudage et de manchonnage','adapter'],['Moyens humains et habilitations','adapter'],['Moyens matériels','adapter'],['Qualité : autocontrôle, contrôles, épreuves','adapter'],['Sécurité, PPSPS, quarts d\'heure, accueil chantier','pret'],['Planning d\'exécution','adapter'],['Environnement, déchets, nuisances','pret'],['Références récentes en réseau de chaleur','ecrire']];
const ETAT_SEC={pret:['prête','ok'],adapter:['à adapter','warn'],ecrire:['à écrire','bad']};
export const blocsAll=()=>docsAll().filter(d=>d.kind==='bloc'&&!d.deleted);
export function memoireVars(a){const C=calcAffaire(a);const base=Object.assign({},BASE,((a.chiffrage||{}).base)||{});const dn=(C.zones||[]).flatMap(z=>z.rows||[]).reduce((m,r)=>{m[r.dn]=(m[r.dn]||0)+(+r.nb||0);return m;},{});const dns=Object.keys(dn).map(Number).sort((x,y)=>x-y);const cad=dns.map(d=>`DN ${d} : ${nb(dn[d])} soudures`);
  return {nb:C.nb,ml:C.ml,jS:C.jS,jM:C.jM,dns:dns.join(' · '),soudParDn:cad.join(', '),equipes:base.nSoud||3,delai:(a.consult||{}).delai||'',client:a.client||'',nom:a.nom||'',ville:a.ville||''};}
function varsParagraph(a){const v=memoireVars(a);return `Le réseau de ${esc(v.nom)} (${esc(v.ville)}) représente ${nb(v.ml)} ml de tranchée et ${nb(v.nb)} soudures${v.dns?' en DN '+esc(v.dns):''}${v.soudParDn?' ('+esc(v.soudParDn)+')':''}. Aux cadences SCR, cela représente ${nb(v.jS,1)} jours de soudage et ${nb(v.jM,1)} jours de manchonnage pour une équipe de ${v.equipes} soudeurs et un manchonneur${v.delai?', compatibles avec le délai de '+esc(v.delai):''}.`;}
export function memoireHTML(a,canEdit,ctx){const M=a.memoire||{};const secs=M.sections||[];const ro=!canEdit;const si=Math.min(AS().msec||0,Math.max(0,secs.length-1));const s=secs[si];const cnt=k=>secs.filter(x=>x.etat===k).length;const blocs=blocsAll();
  return notesBlock(a,'memoire',canEdit)+`<div class="ac-stats" style="margin-bottom:8px"><div class="ac-stat ${secs.length&&cnt('pret')===secs.length?'ok':''}"><b>${cnt('pret')} / ${secs.length}</b><small>sections prêtes</small></div><div class="ac-stat ${cnt('adapter')?'warn':''}"><b>${cnt('adapter')}</b><small>à adapter</small></div><div class="ac-stat ${cnt('ecrire')?'bad':''}"><b>${cnt('ecrire')}</b><small>à écrire</small></div><div class="ac-stat"><b>${blocs.length}</b><small>blocs SCR en bibliothèque</small></div></div>
    ${secs.length?`<div class="cm-mem"><div class="card"><h3>Plan du mémoire <span class="hint">· critères du RC : ${esc((a.consult||{}).criteres||'à renseigner (Dossier)')}</span></h3>
        ${secs.map((x,i)=>`<button class="cm-sec${i===si?' on':''}" data-act="af" data-v="msec|${i}"><span class="n">${i+1}</span><span class="tx"><b>${esc(x.titre||'(sans titre)')}</b><small>${x.texte?nb(String(x.texte).split(/\s+/).filter(Boolean).length)+' mots':'vide'}${x.bloc?' · bloc « '+esc(x.bloc)+' »':''}</small></span><span class="eq-tag ${ETAT_SEC[x.etat]?ETAT_SEC[x.etat][1]:''}">${ETAT_SEC[x.etat]?ETAT_SEC[x.etat][0]:x.etat||''}</span></button>`).join('')}
        ${canEdit?`<div class="eq-acts" style="margin-top:8px"><button class="btn sm" data-act="af" data-v="msecadd|">＋ Section</button><button class="btn sm" data-act="af" data-v="msecup|">↑</button><button class="btn sm" data-act="af" data-v="msecdown|">↓</button><button class="btn sm" data-act="af" data-v="mprint|">🖨 Imprimer / PDF</button><button class="btn sm" data-act="af" data-v="mword|">⬇ Word (.doc)</button></div>`:''}</div>
      <div class="card">${s?`<div class="row" style="display:flex;gap:6px;flex-wrap:wrap"><div style="flex:2;min-width:180px"><label class="f">Section ${si+1}</label><input class="f" data-afm="titre" value="${esc(s.titre||'')}" ${ro?'disabled':''}></div><div style="flex:1;min-width:120px"><label class="f">État</label><select class="f" data-afm="etat" ${ro?'disabled':''}>${Object.keys(ETAT_SEC).map(k=>`<option value="${k}"${s.etat===k?' selected':''}>${ETAT_SEC[k][0]}</option>`).join('')}</select></div></div>
        <label class="f">Texte <span class="dim">(un paragraphe par ligne vide ; « À ADAPTER : … » pour ce qui reste à écrire)</span></label><textarea class="f cm-editor" data-afm="texte" ${ro?'disabled':''}>${esc(s.texte||'')}</textarea>
        ${canEdit?`<div class="eq-acts" style="margin-top:8px"><button class="btn sm" data-act="af" data-v="mvars|">⟳ Paragraphe depuis le chiffrage</button><select class="f" id="cm-bloc" style="min-width:140px;max-width:220px"><option value="">📚 Insérer un bloc…</option>${blocs.map(b=>`<option value="${esc(b.id)}">${esc(b.title)}</option>`).join('')}</select><button class="btn sm" data-act="af" data-v="mbloc|">Insérer</button><button class="btn sm" data-act="af" data-v="msave|" title="Garder ce texte dans la bibliothèque SCR pour les prochains dossiers">💾 Garder comme bloc SCR</button><button class="btn sm primary" data-act="af" data-v="mpret|">✓ Prête</button><button class="btn sm" data-act="af" data-v="msecrm|" style="color:#9b2c22;margin-left:auto">✕ Section</button></div>`:''}
        ${blocs.length?`<div class="eq-lab" style="margin-top:8px">Blocs SCR dans cette section <span class="dim">· coche pour insérer une copie (modifiable ici, le bloc de la base reste inchangé)</span></div><div class="cm-blocsel">${blocs.map(b=>{const on=(s.blocs||[]).some(x=>x.id===b.id);return `<label class="cm-tache${on?' done':''}" style="min-height:38px;padding:5px 8px"><input type="checkbox" ${on?'checked':''} ${ro?'disabled':''} data-act="af" data-v="mbloctoggle|${esc(b.id)}"><span><b>${esc(b.title)}</b><small>${esc(b.src||'')}${b.by?' · '+esc(b.by):''} · ${nb(String(b.html||'').split(/\s+/).filter(Boolean).length)} mots</small></span></label>`;}).join('')}</div>`:''}`:'<div class="eq-s">Choisis une section.</div>'}</div></div>`
    :`<div class="card"><h3>Pas encore de mémoire pour cette affaire</h3><div class="eq-s">Le plan type SCR (10 sections : présentation, compréhension du projet, méthodologie soudage / manchonnage, moyens humains, moyens matériels, qualité, sécurité, planning, environnement, références) se crée en une touche ; chaque section part d'un bloc SCR ou se rédige ici, et les chiffres (soudures, cadences, délai) viennent du chiffrage.</div>${canEdit?`<div class="eq-acts" style="margin-top:8px"><button class="btn primary" data-act="af" data-v="mplan|">Créer le plan type SCR</button></div>`:''}</div>`}
    ${blocs.length||canEdit?`<div class="card"><h3>Bibliothèque de blocs SCR <span class="hint">· textes validés sur des dossiers gagnés, réutilisables — modifiés ici, ils changent pour les prochains dossiers seulement</span></h3>${blocs.length?blocs.map(b=>`<div class="eq-row" style="min-height:40px"><span class="eq-grow"><span class="eq-t">${esc(b.title)}</span><span class="eq-s">${esc(b.src||'')}${b.by?' · '+esc(b.by):''} · ${dFR(b.at)} · ${nb(String(b.html||'').split(/\s+/).filter(Boolean).length)} mots</span></span>${canEdit?`<button class="btn sm" data-act="af" data-v="blocedit|${esc(b.id)}">✎</button><button class="btn sm" data-act="af" data-v="blocrm|${esc(b.id)}" style="color:#9b2c22">✕</button>`:''}</div>`).join(''):'<div class="eq-s">Vide : « 💾 Garder comme bloc SCR » sur une section la range ici, ou passe le SQL sql/blocs_memoire_scr.sql (mémoire O2410-10 découpé en blocs).</div>'}${canEdit?`<div class="eq-acts" style="margin-top:6px"><button class="btn sm" data-act="af" data-v="blocnew|">＋ Nouveau bloc</button></div>`:''}</div>`:''}`;}
function blocModal(b,render){const isNew=!b;b=b||{};A.openModal(`<h3 style="margin-top:0">${isNew?'Nouveau bloc SCR':'Modifier le bloc'}</h3><label class="f">Titre</label><input class="f" id="bl-title" value="${esc(b.title||'')}" placeholder="ex. Méthodologie de manchonnage électrosoudable"><label class="f">Source <span class="dim">(dossier d'origine)</span></label><input class="f" id="bl-src" value="${esc(b.src||'')}"><label class="f">Texte</label><textarea class="f cm-editor" id="bl-text" style="min-height:220px">${esc(b.html||'')}</textarea><div class="actions" style="margin-top:8px"><button class="btn primary block" id="bl-ok">${isNew?'Créer le bloc':'Enregistrer'}</button><button class="btn block" data-close>Annuler</button></div>`);
  document.getElementById('bl-ok').onclick=()=>{const g=id=>(document.getElementById(id)||{}).value||'';const title=g('bl-title').trim();if(!title){A.toast('Le titre');return;}const id=isNew?'bloc_'+Date.now().toString(36):b.id;regSet('doc',id,Object.assign(isNew?{kind:'bloc',req:{none:true},by:A.userName?A.userName():'',at:new Date().toISOString()}:{},{title,src:g('bl-src').trim(),html:g('bl-text')}));A.closeModal();A.toast(isNew?'Bloc créé':'Bloc enregistré — les sections qui l\'ont copié ne changent pas');render();};}
export function memoireDocHTML(a){const secs=((a.memoire||{}).sections||[]);const p=t=>String(t||'').split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean).map(x=>`<p>${esc(x).replace(/\n/g,'<br>')}</p>`).join('');
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Mémoire technique — ${esc(a.num)} ${esc(a.nom||'')}</title><style>body{font:12pt Calibri,Arial,sans-serif;color:#111;max-width:800px;margin:30px auto;line-height:1.45}h1{font-size:22pt;color:#eb6834;margin:0 0 4px}h2{font-size:14pt;color:#14213d;margin:22px 0 6px;border-bottom:1px solid #ccc;padding-bottom:3px}p{margin:0 0 8px}.sub{color:#666;margin:0 0 18px}.todo{background:#fff4d6}@media print{body{margin:0}}</style></head><body><h1>Mémoire technique</h1><div class="sub">${esc(a.num)} · ${esc(a.nom||'')} · ${esc(a.client||'')}${a.ville?' · '+esc(a.ville):''} · SCR</div>${secs.map((s,i)=>`<h2>${i+1}. ${esc(s.titre||'')}</h2>${p(s.texte).replace(/À ADAPTER[^<]*/g,m=>'<span class="todo">'+m+'</span>')||'<p><i>(à écrire)</i></p>'}`).join('')}</body></html>`;}
