/* lecture d'un .xlsx SANS bibliothèque : zip (répertoire central) + DecompressionStream('deflate-raw') + XML (sharedStrings, sheet1). Sinon : collage depuis Excel (tabulations). */
async function zipEntries(buf){const dv=new DataView(buf);const u8=new Uint8Array(buf);let eocd=-1;for(let i=buf.byteLength-22;i>=Math.max(0,buf.byteLength-70000);i--){if(dv.getUint32(i,true)===0x06054b50){eocd=i;break;}}if(eocd<0)throw new Error('zip');
  const n=dv.getUint16(eocd+10,true),cd=dv.getUint32(eocd+16,true);const out={};let p=cd;const td=new TextDecoder();
  for(let k=0;k<n;k++){if(dv.getUint32(p,true)!==0x02014b50)break;const method=dv.getUint16(p+10,true),csize=dv.getUint32(p+20,true),nl=dv.getUint16(p+28,true),el=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true),off=dv.getUint32(p+42,true);const name=td.decode(u8.subarray(p+46,p+46+nl));
    const lnl=dv.getUint16(off+26,true),lel=dv.getUint16(off+28,true);const start=off+30+lnl+lel;out[name]={method,data:u8.subarray(start,start+csize)};p+=46+nl+el+cl;}
  return out;}
async function inflate(e){if(e.method===0)return new TextDecoder().decode(e.data);if(typeof DecompressionStream==='undefined')throw new Error('Ce navigateur ne sait pas décompresser : colle les lignes depuis Excel');const ds=new DecompressionStream('deflate-raw');const w=ds.writable.getWriter();w.write(e.data);w.close();const buf=await new Response(ds.readable).arrayBuffer();return new TextDecoder().decode(buf);}
export async function xlsxRows(file,opt){const buf=await file.arrayBuffer(); /* 13/10 : opt.grid = colonnes à leur place (A=0, B=1…, cases vides gardées) — l'import de commande lit les colonnes par en-tête */const Z=await zipEntries(buf);const names=Object.keys(Z);const sheet=names.find(x=>x==='xl/worksheets/sheet1.xml')||names.filter(x=>/^xl\/worksheets\/sheet\d+\.xml$/.test(x)).sort()[0];if(!sheet)throw new Error('pas de feuille');
  const SS=[];if(Z['xl/sharedStrings.xml']){const x=new DOMParser().parseFromString(await inflate(Z['xl/sharedStrings.xml']),'application/xml');[...x.getElementsByTagName('si')].forEach(si=>SS.push([...si.getElementsByTagName('t')].map(t=>t.textContent).join('')));}
  const x=new DOMParser().parseFromString(await inflate(Z[sheet]),'application/xml');const rows=[];rows._sheet=sheet;
  [...x.getElementsByTagName('row')].forEach(r=>{const cells={};[...r.getElementsByTagName('c')].forEach(c=>{const ref=c.getAttribute('r')||'';const col=ref.replace(/\d+/g,'');const t=c.getAttribute('t');let v='';const V=c.getElementsByTagName('v')[0];if(t==='s'){v=SS[+(V?V.textContent:0)]||'';}else if(t==='inlineStr'){v=[...c.getElementsByTagName('t')].map(z=>z.textContent).join('');}else if(V){v=V.textContent;}cells[col]=v;});
    const cols=Object.keys(cells).sort((p,q)=>p.length-q.length||p.localeCompare(q));if(opt&&opt.grid){const ci=c=>[...c].reduce((n,ch)=>n*26+(ch.charCodeAt(0)-64),0)-1;const row=[];cols.forEach(k=>{const i=ci(k);if(i>=0&&i<200)row[i]=cells[k];});for(let i=0;i<row.length;i++)if(row[i]===undefined)row[i]='';row._r=+r.getAttribute('r')||0;rows.push(row);}else{const row=cols.map(k=>cells[k]);row._r=+r.getAttribute('r')||0;rows.push(row);}});
  return rows;}
export function pasteRows(txt){return String(txt||'').replace(/\r/g,'').split('\n').filter(l=>l.trim()).map(l=>l.split(l.includes('\t')?'\t':';').map(c=>c.trim().replace(/^"|"$/g,'')));}
/* lignes du bordereau : en-tête reconnu (n°, désignation, unité, quantité, PU) ; titres de chapitre gardés (sans unité ni quantité) */
export function dpgfFromRows(rows,meta){const low=r=>r.map(c=>String(c||'').toLowerCase());let hi=rows.findIndex(r=>low(r).some(c=>/d[ée]signation|libell[ée]|d[ée]tail des prix/.test(c)));if(hi<0)hi=rows.findIndex(r=>low(r).filter(c=>c).length>=3);if(hi<0)return [];
  const H=low(rows[hi]);const find=re=>H.findIndex(c=>re.test(c));let iN=find(/^n[°o]?\s*$|^num|^n°|^art|^poste|^r[ée]f/),iD=find(/d[ée]signation|libell[ée]|d[ée]tail/),iU=find(/^u(nit[ée]s?)?\.?$|^unit/),iQ=find(/quant|^qt[ée]/),iP=find(/p\.?\s?u|prix\s*u|unitaire/),iT=find(/^total|^montant|prix\s*total/);
  if(iD<0)iD=H.findIndex((c,i)=>i!==iN&&c);if(iD<0)return [];
  if(meta){meta.hdrRow=rows[hi]._r||hi+1;meta.cols={n:iN,des:iD,u:iU,qte:iQ,pu:iP,tot:iT};meta.sheet=rows._sheet||null;} /* 13/10 : pour réécrire les PU dans le fichier Excel du client */
  const num=v=>{const s=String(v||'').replace(/\s/g,'').replace(',','.');const x=parseFloat(s);return isFinite(x)?x:null;};const L=[];
  rows.slice(hi+1).forEach((r,k)=>{const des=String(r[iD]||'').trim();if(!des)return;const n=iN>=0?String(r[iN]||'').trim():'';const u=iU>=0?String(r[iU]||'').trim():'';const q=iQ>=0?num(r[iQ]):null;const pu=iP>=0?num(r[iP]):null;if(/^total/i.test(des))return;const row=r._r||(hi+2+k);
    if(!u&&q===null){L.push({n,des,section:true,row});return;}L.push({n,des,u,qte:q||0,pu:pu||0,row});});
  return L;}
const srcOf=l=>/soud|tube|canalisation|dn\s?\d|pr[ée]-?isol/i.test(l.des)?['chiffrage · tubes & soudure','or']:/manchon|jonction/i.test(l.des)?['chiffrage · manchons',' or']:/radio|contr[ôo]le|cnd|[ée]preuve|essai/i.test(l.des)?['chiffrage · contrôles','or']:/coude|t[ée]\b|r[ée]duction|vanne|pi[èe]ce/i.test(l.des)?['fourniture + pose','blue']:['forfait','grey'];
/* le reste (centimes d'arrondi) va sur la ligne à la plus petite quantité : avec un forfait à 1, le total tombe juste au centime */
function absorb(lines,target){const L=lines.filter(l=>(+l.qte||0)>0);if(!L.length)return;const tot=L.reduce((s,l)=>s+(+l.pu||0)*(+l.qte||0),0);const rest=Math.round((target-tot)*100)/100;if(!rest)return;const sm=L.slice().sort((x,y)=>(+x.qte)-(+y.qte))[0];sm.pu=Math.round(((+sm.pu||0)*(+sm.qte)+rest)/(+sm.qte)*100)/100;}
export function dpgfHTML(a,canEdit,ctx){const D=a.dpgf||{};const L=D.lignes||[];const lines=L.filter(l=>!l.section);const C=calcAffaire(a);const tot=lines.reduce((s,l)=>s+(+l.pu||0)*(+l.qte||0),0);const ecart=Math.abs(tot-C.total)<0.5?0:Math.round((tot-C.total)*100)/100;const ro=!canEdit;const ml=(a.quantites||{}).ml||C.ml||0;
  const checks=[[Math.abs(ecart)<1,'Total DPGF = prix de vente du chiffrage ('+eur(C.total)+')'],[lines.length>0&&lines.every(l=>+l.pu>0),'Toutes les lignes ont un prix (aucune à 0)'],[true,'Quantités = celles du fichier du client (non modifiées ici)'],[!!a.montant&&Math.abs((+a.montant||0)-tot)<1,'Montant du devis (fiche) = total DPGF'+(a.montant?'':' — se remplit à la remise de l\'offre')]];
  return `<div class="ac-stats" style="margin-bottom:8px"><div class="ac-stat or"><b>${eur(tot)}</b><small>total DPGF HT</small></div><div class="ac-stat"><b>${eur(C.total)}</b><small>prix de vente du chiffrage${a.chiffrageV?' · v'+a.chiffrageV:''}</small></div><div class="ac-stat ${!lines.length?'':Math.abs(ecart)<1?'ok':Math.abs(ecart)>500?'bad':'warn'}"><b>${lines.length?(ecart>0?'+':'')+eur(ecart):'—'}</b><small>écart à résorber</small></div><div class="ac-stat"><b>${lines.length}</b><small>lignes${D.src?' · '+esc(D.src):''}</small></div><div class="ac-stat"><b>${ml?nb(tot/ml)+' €':'—'}</b><small>par ml de tranchée</small></div></div>
    ${L.length?`<div class="card"><h3>Le bordereau du client <span class="hint">· ${esc(D.fichier||D.src||'')} · PU = ta stratégie, le client ne voit que PU × quantité</span></h3>
      ${canEdit?`<div class="eq-acts" style="margin:0 0 6px"><button class="btn sm" data-act="af" data-v="dprep|">⚖ Répartir le prix de vente sur les lignes</button><button class="btn sm" data-act="af" data-v="dpround|">Arrondir à l'euro</button><button class="btn sm" data-act="af" data-v="dpcsv|">⬇ CSV (Excel)</button><button class="btn sm" data-act="af" data-v="dpprint|">🖨</button><button class="btn sm" data-act="af" data-v="dpclear|" style="color:#9b2c22;margin-left:auto">✕ Réimporter</button></div>`:''}
      <div style="overflow:auto"><table class="rc af-tab cm-dpgf"><tr><th>N°</th><th>Désignation</th><th>U</th><th class="num">Qté</th><th class="num">PU HT</th><th class="num">Total HT</th><th>Source</th></tr>${L.map((l,i)=>l.section?`<tr class="sub"><td>${esc(l.n||'')}</td><td colspan="6">${esc(l.des)}</td></tr>`:`<tr><td>${esc(l.n||'')}</td><td>${esc(l.des)}</td><td>${esc(l.u||'')}</td><td class="num">${nb(l.qte,String(l.qte).includes('.')?2:0)}</td><td class="num"><input class="f af-n cm-pu" type="number" step="0.01" min="0" data-afdp="${i}" value="${l.pu?esc(l.pu):''}" ${ro?'disabled':''}></td><td class="num"><b>${eur((+l.pu||0)*(+l.qte||0))}</b></td><td><span class="eq-tag ${srcOf(l)[1].trim()}">${srcOf(l)[0]}</span></td></tr>`).join('')}<tr class="tot"><td></td><td>Total DPGF HT</td><td></td><td></td><td></td><td class="num">${eur(tot)}</td><td>${Math.abs(ecart)<1?'<span class="eq-tag ok">= prix de vente</span>':`<span class="eq-tag ${Math.abs(ecart)>500?'bad':'warn'}">écart ${ecart>0?'+':''}${eur(ecart)}</span>`}</td></tr></table></div></div>
      ${dpgfMapHTML(a,canEdit)}
      <div class="card"><h3>Contrôles avant export</h3><div class="cm-taches">${checks.map(c=>`<label class="cm-tache${c[0]?' done':''}"><input type="checkbox" ${c[0]?'checked':''} disabled><span><b>${c[1]}</b></span></label>`).join('')}</div><div class="hint" style="margin-top:6px">Export : ${D.kept?'« Excel du client rempli » réécrit les PU dans son fichier (mise en forme conservée) ; sinon ':''}CSV à ouvrir dans Excel (séparateur « ; », décimales à virgule). Après attribution, ce bordereau devient le tableau de facturation (situations par ligne).</div></div>`
    :`<div class="card"><h3>Importer la DPGF du maître d'œuvre</h3><div class="eq-s">Le fichier Excel du DCE tel quel (.xlsx) : les colonnes n°, désignation, unité, quantité (et PU s'il y en a) sont reconnues ; les titres de chapitre sont gardés. Ou colle les lignes depuis Excel (Ctrl+C dans Excel, Ctrl+V ici).</div>
      ${canEdit?`<div class="eq-acts" style="margin-top:8px"><label class="btn primary">📎 Fichier DPGF (.xlsx, .csv)<input type="file" accept=".xlsx,.csv,.txt" data-afdpgf="${esc(a.num)}" style="display:none"></label></div><label class="f" style="margin-top:8px">… ou coller depuis Excel</label><textarea class="f" id="cm-paste" style="min-height:90px" placeholder="N°	Désignation	U	Quantité&#10;2.1	Fourniture et pose tube DN 250	ml	1240"></textarea><div class="eq-acts" style="margin-top:6px"><button class="btn" data-act="af" data-v="dppaste|">Lire le collage</button></div>`:''}</div>`}`;}
export function dpgfCSV(a){const L=((a.dpgf||{}).lignes||[]);const f=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const n=v=>String(+v||0).replace('.',',');return '﻿'+['N°;Désignation;U;Quantité;PU HT;Total HT'].concat(L.map(l=>l.section?[f(l.n),f(l.des),'','','',''].join(';'):[f(l.n),f(l.des),f(l.u),n(l.qte),n(l.pu),n((+l.pu||0)*(+l.qte||0))].join(';'))).join('\r\n')+'\r\n';}
