const PIECES_OFFRE=[['ae','Acte d\'engagement (AE) signé — montant = prix de vente'],['dpgf','DPGF remplie (Excel du client + PDF signé)'],['memoire','Mémoire technique'],['planning','Planning d\'exécution'],['attest','Attestations (URSSAF, assurance, Kbis, qualifications des soudeurs)'],['variante','Variante (si autorisée) : chiffrage et note'] ];
export function offreHTML(a,canEdit,ctx){const O=a.offre||{};const P=O.pieces||{};const st=stepState(a);const C=st.C;const today=todayIso();const J=a.dateReponse?jours(today,a.dateReponse):null;const V=a.chiffrages||[];const ok=PIECES_OFFRE.filter(p=>P[p[0]]).length;const ro=!canEdit;const remis=!!O.remiseAt;
  return `<div class="ac-stats" style="margin-bottom:8px"><div class="ac-stat or"><b>${C.total?eur(C.total):'—'}</b><small>prix de vente HT · v${a.chiffrageV||1}</small></div><div class="ac-stat"><b>${esc((a.consult||{}).delai||'—')}</b><small>délai proposé</small></div><div class="ac-stat ${ok===PIECES_OFFRE.length?'ok':ok?'warn':''}"><b>${ok} / ${PIECES_OFFRE.length}</b><small>pièces prêtes</small></div><div class="ac-stat ${remis?'ok':J===null?'':J<0?'bad':J<=3?'warn':''}"><b>${remis?dFR(O.remiseAt):(J===null?'—':J<0?'dépassée':'J-'+J)}</b><small>${remis?'offre remise':'remise '+(a.dateReponse?dFR(a.dateReponse):'')}</small></div><div class="ac-stat"><b>${V.length+1}</b><small>version${V.length?'s':''} du chiffrage</small></div></div>
    <div class="cm-mem"><div class="card"><h3>Pièces à remettre <span class="hint">· ${(a.consult||{}).plateforme?`<a href="${esc(a.consult.plateforme)}" target="_blank" rel="noopener">plateforme de dépôt</a>`:'plateforme : voir Dossier'}${a.dateReponse?' · avant le '+dFR(a.dateReponse)+((a.consult||{}).remiseHeure?' '+esc(a.consult.remiseHeure):''):''}</span></h3>
        <div class="cm-taches">${PIECES_OFFRE.map(([k,l])=>`<label class="cm-tache${P[k]?' done':''}"><input type="checkbox" ${P[k]?'checked':''} ${ro?'disabled':''} data-act="af" data-v="opiece|${k}"><span><b>${l}</b>${k==='memoire'&&!st.memoire&&((a.memoire||{}).sections||[]).length?'<small>sections pas toutes prêtes</small>':k==='dpgf'&&!st.dpgf&&st.L.length?'<small>écart DPGF / chiffrage</small>':''}</span></label>`).join('')}</div>
        ${canEdit?`<div class="eq-acts" style="margin-top:10px">${remis?`<span class="eq-tag ok">📤 remise le ${dFR(O.remiseAt)}${O.montant?' · '+eur(O.montant):''}</span>`:`<button class="btn primary" data-act="af" data-v="oremise|">📤 Marquer l'offre remise</button>`}<button class="btn" data-act="af" data-v="mprint|">🖨 Mémoire</button><button class="btn" data-act="af" data-v="print|">🖨 Fiche de chiffrage</button></div>`:''}</div>
      <div class="card"><h3>Après la remise</h3>
        ${remis?`<div class="cm-suivi">${['a_debuter','en_cours','termine'].includes(a.etat)?`<div class="okbox">🏆 Gagnée${O.gagneAt?' le '+dFR(O.gagneAt):''} — dossier en cours : chantier lié, tableau de facturation (onglet Facturation).</div>`:a.etat==='perdu'?`<div class="warnbox">✗ Perdue${O.perduAt?' le '+dFR(O.perduAt):''}${O.motif?' · '+esc(O.motif):''}${O.prixGagnant?' · prix du gagnant : '+eur(O.prixGagnant):''} — la traçabilité reste dans le Reporting.</div>`:`<div class="eq-s">Négociation, alignement technique, variante : <b>＋ Nouvelle version</b> du chiffrage (la précédente est gardée), puis gagnée ou perdue.</div>${canEdit?`<div class="eq-acts" style="margin-top:8px"><button class="btn" data-act="af" data-v="vnew|">＋ Nouvelle version (négociation)</button><button class="btn primary" data-act="af" data-v="ogagne|">🏆 Gagnée → à débuter</button><button class="btn" data-act="af" data-v="operdu|" style="color:#9b2c22">✗ Perdue</button></div>`:''}`}</div>`:'<div class="eq-s">Une fois l\'offre remise : négociation (versions du chiffrage), puis gagnée (→ dossier en cours) ou perdue (motif, prix du gagnant si connu).</div>'}
        <div class="eq-lab" style="margin-top:8px">Versions du chiffrage</div>${V.map(x=>`<div class="eq-row" style="min-height:36px"><span class="eq-grow"><span class="eq-t">v${x.v} · ${esc(x.note||'')}</span><span class="eq-s">${esc(x.by||'')} · ${dFR(x.at)} · ${eur(x.total||0)}</span></span></div>`).join('')}<div class="eq-row" style="min-height:36px"><span class="eq-grow"><span class="eq-t">v${a.chiffrageV||1} · ${esc(a.chiffrageNote||'version en cours')}</span><span class="eq-s">${eur(C.total)}</span></span></div>
        <div class="hint" style="margin-top:8px">Le Reporting garde : créée le ${dFR(a.at)||'—'}, remise ${remis?dFR(O.remiseAt):'—'}, montant, marge ${nb((C.marge||0)*100)} %, versions, chargé d'affaires ${esc(a.charge||'')}.</div></div></div>`;}
/* ═════════ actions et saisies (appelées par affaires.js) ═════════ */
const AS=()=>affState();
export function commerceAct(k,arg,arg2,arg3,ctx){const a=AS().cur?affGet(AS().cur):null;if(!a)return false;const canEdit=ctx.canEdit;const say=t=>A&&A.toast&&A.toast(t);const upd=p=>affSet(a.num,p);const render=()=>{if(ctx.render)ctx.render();};
  switch(k){
    case 'lectdest':AS().lectDest=arg||'';render();return true;
    case 'notedone':{if(!canEdit)return true;const dest=String(arg3||'');upd({dce:(a.dce||[]).map(d=>d.id!==arg?d:Object.assign({},d,{notes:(d.notes||[]).map((n,j)=>j!==+arg2?n:Object.assign({},n,{done:Object.assign({},n.done||{},{[dest]:!(n.done&&n.done[dest])})}))}))});render();return true;}
    case 'tache':{if(!canEdit)return true;const T=Object.assign({},a.taches||{});T[arg]=!T[arg];upd({taches:T});render();return true;}
    case 'qadd':{if(!canEdit)return true;const q=Object.assign({rows:[]},a.quantites||{});q.rows=(q.rows||[]).concat([{dn:q.rows&&q.rows.length?q.rows[q.rows.length-1].dn:250,soud:'',ml:''}]);upd({quantites:q});render();return true;}
    case 'qrm':{if(!canEdit)return true;const q=Object.assign({rows:[]},a.quantites||{});q.rows=(q.rows||[]).filter((x,i)=>i!==+arg);upd({quantites:q});render();return true;}
    case 'qprefill':{if(!canEdit)return true;const q=a.quantites||{};const rows=(q.rows||[]).filter(r=>+r.dn&&(+r.soud||+r.ml)).map(r=>({dn:+r.dn,nb:+r.soud||0,ml:+r.ml||0}));if(!rows.length){say('Renseigne au moins un DN avec ses soudures');return true;}
      if(prixBase()){ /* chiffrage v2 : la zone « Quantités repérées » (étude) est créée ou mise à jour (ses DN seulement) */const E=etudesOf(a);let zi=E.findIndex(z=>z.source==='quantites');if(zi<0){zi=etudeAdd(a,etudeFromRows(rows,'Quantités repérées','quantites'));}else{const ch=Object.assign({},a.chiffrage||{});ch.etudes=ch.etudes.map((z,i)=>i===zi?Object.assign({},z,{dn:rows.map(r=>({dn:r.dn,soud:r.nb,ml:r.ml}))}):z);upd({chiffrage:ch});}
        chiffrageState().ei=zi;chiffrageState().view='etude';AS().tab='chiffrage';render();say('Chiffrage prérempli : '+rows.length+' DN depuis les quantités repérées');return true;}
      const ch=Object.assign({zones:[],chapitres:[]},a.chiffrage||{});ch.zones=(ch.zones||[]).slice();let zi=ch.zones.findIndex(z=>z.source==='quantites');if(zi<0){ch.zones.push({nom:'Quantités repérées',rows,source:'quantites'});zi=ch.zones.length-1;}else ch.zones[zi]=Object.assign({},ch.zones[zi],{rows});upd({chiffrage:ch});AS().zone=zi;AS().tab='chiffrage';render();say('Chiffrage prérempli : '+rows.length+' DN depuis les quantités repérées');return true;}
    case 'msec':AS().msec=+arg;render();return true;
    case 'mplan':{if(!canEdit)return true;upd({memoire:{sections:PLAN_SCR.map(([t,e],i)=>({id:'S'+(i+1),titre:t,etat:e,texte:''})),at:new Date().toISOString()}});AS().msec=0;render();return true;}
    case 'msecadd':{if(!canEdit)return true;const M=Object.assign({},a.memoire||{});M.sections=(M.sections||[]).concat([{id:'S'+Date.now().toString(36),titre:'Nouvelle section',etat:'ecrire',texte:''}]);upd({memoire:M});AS().msec=M.sections.length-1;render();return true;}
    case 'msecrm':{if(!canEdit)return true;const M=Object.assign({},a.memoire||{});const i=AS().msec||0;if(!confirm('Retirer cette section du mémoire ?'))return true;M.sections=(M.sections||[]).filter((x,j)=>j!==i);upd({memoire:M});AS().msec=Math.max(0,i-1);render();return true;}
    case 'msecup':case 'msecdown':{if(!canEdit)return true;const M=Object.assign({},a.memoire||{});const S=(M.sections||[]).slice();const i=AS().msec||0;const j=k==='msecup'?i-1:i+1;if(j<0||j>=S.length)return true;[S[i],S[j]]=[S[j],S[i]];M.sections=S;upd({memoire:M});AS().msec=j;render();return true;}
    case 'mpret':{if(!canEdit)return true;const M=Object.assign({},a.memoire||{});const i=AS().msec||0;M.sections=(M.sections||[]).map((s,j)=>j===i?Object.assign({},s,{etat:'pret'}):s);upd({memoire:M});render();say('Section prête');return true;}
    case 'mvars':{if(!canEdit)return true;const M=Object.assign({},a.memoire||{});const i=AS().msec||0;const s=(M.sections||[])[i];if(!s)return true;const ta=document.querySelector('#eq-app [data-afm=texte]');const cur=ta?ta.value:(s.texte||'');const txt=(cur?cur.replace(/\s+$/,'')+'\n\n':'')+varsParagraph(a).replace(/&#39;/g,"'").replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>');M.sections=M.sections.map((x,j)=>j===i?Object.assign({},x,{texte:txt}):x);upd({memoire:M});render();say('Paragraphe inséré depuis le chiffrage v'+(a.chiffrageV||1));return true;}
    case 'mbloc':{if(!canEdit)return true;const sel=document.getElementById('cm-bloc');const b=sel&&sel.value?blocsAll().find(x=>x.id===sel.value):null;if(!b){say('Choisis un bloc dans la liste');return true;}const M=Object.assign({},a.memoire||{});const i=AS().msec||0;const ta=document.querySelector('#eq-app [data-afm=texte]');const cur=ta?ta.value:((M.sections||[])[i]||{}).texte||'';M.sections=(M.sections||[]).map((x,j)=>j===i?Object.assign({},x,{texte:(cur?cur.replace(/\s+$/,'')+'\n\n':'')+String(b.html||''),bloc:b.title,etat:x.etat==='ecrire'?'adapter':x.etat}):x);upd({memoire:M});render();say('Bloc « '+b.title+' » inséré');return true;}
    case 'msave':{if(!canEdit)return true;const i=AS().msec||0;const s=((a.memoire||{}).sections||[])[i];const ta=document.querySelector('#eq-app [data-afm=texte]');const txt=(ta?ta.value:(s&&s.texte))||'';if(!txt.trim()){say('La section est vide');return true;}const title=prompt('Nom du bloc dans la bibliothèque SCR :',s?s.titre:'');if(!title)return true;
      regSet('doc','bloc_'+Date.now().toString(36),{kind:'bloc',title:String(title).trim(),html:txt,src:a.num+' · '+(a.nom||''),req:{none:true},by:A.userName?A.userName():'',at:new Date().toISOString()});render();say('💾 Bloc SCR enregistré : « '+title+' »');return true;}
    case 'mbloctoggle':{if(!canEdit)return true;const b=blocsAll().find(x=>x.id===arg);if(!b)return true;const M=Object.assign({},a.memoire||{});const i=AS().msec||0;const s=(M.sections||[])[i];if(!s)return true;const ta=document.querySelector('#eq-app [data-afm=texte]');const cur=ta?ta.value:(s.texte||'');const on=(s.blocs||[]).some(x=>x.id===arg);
      if(!on){const txt=(cur?cur.replace(/\s+$/,'')+'\n\n':'')+String(b.html||'');M.sections=M.sections.map((x,j)=>j===i?Object.assign({},x,{texte:txt,blocs:(x.blocs||[]).concat([{id:b.id,title:b.title,at:new Date().toISOString()}]),bloc:b.title,etat:x.etat==='ecrire'?'adapter':x.etat}):x);say('Bloc « '+b.title+' » copié dans la section');}
      else{const body=String(b.html||'');let txt=cur;if(body&&cur.includes(body))txt=cur.replace(body,'').replace(/\n{3,}/g,'\n\n').trim();else if(!confirm('Le texte du bloc a été modifié dans cette section : le retirer de la liste sans toucher au texte ?'))return true;M.sections=M.sections.map((x,j)=>j===i?Object.assign({},x,{texte:txt,blocs:(x.blocs||[]).filter(y=>y.id!==arg)}):x);}
      upd({memoire:M});render();return true;}
    case 'blocedit':{if(!canEdit)return true;const b=blocsAll().find(x=>x.id===arg);if(b)blocModal(b,render);return true;}
    case 'blocnew':{if(!canEdit)return true;blocModal(null,render);return true;}
    case 'blocrm':{if(!canEdit)return true;if(!confirm('Retirer ce bloc de la bibliothèque ?'))return true;regSet('doc',arg,{deleted:true,deletedAt:new Date().toISOString()});render();return true;}
    case 'mprint':{const w=window.open('','_blank');if(!w){say('Autorise les fenêtres pour imprimer');return true;}w.document.write(memoireDocHTML(a));w.document.close();setTimeout(()=>{try{w.print();}catch(e){}},300);return true;}
    case 'mword':{try{const blob=new Blob(['﻿'+memoireDocHTML(a)],{type:'application/msword'});const u=URL.createObjectURL(blob);const l=document.createElement('a');l.href=u;l.download='Memoire_technique_'+String(a.num).replace(/[^A-Za-z0-9-]/g,'_')+'.doc';document.body.appendChild(l);l.click();setTimeout(()=>{URL.revokeObjectURL(u);l.remove();},2000);say('⬇ Mémoire technique (.doc) — s\'ouvre dans Word');}catch(e){console.warn(e);}return true;}
    case 'dppaste':{if(!canEdit)return true;const ta=document.getElementById('cm-paste');const L=dpgfFromRows(pasteRows(ta?ta.value:''));if(!L.length){say('Rien de lisible : il faut une ligne d\'en-tête (N°, Désignation, Unité, Quantité) puis les lignes');return true;}upd({dpgf:{lignes:L,src:'collé depuis Excel',at:new Date().toISOString()}});render();say('DPGF lue : '+L.filter(l=>!l.section).length+' lignes');return true;}
    case 'dpclear':{if(!canEdit)return true;if(!confirm('Retirer la DPGF importée (les PU saisis seront perdus) ?'))return true;upd({dpgf:null});render();return true;}
    case 'dprep':{if(!canEdit)return true;const D=Object.assign({},a.dpgf||{});const C=calcAffaire(a);if(!C.total){say('Fais d\'abord le chiffrage : rien à répartir');return true;}const L=(D.lignes||[]).map(l=>Object.assign({},l));const lines=L.filter(l=>!l.section);const w=lines.map(l=>(+l.pu||0)*(+l.qte||0)>0?(+l.pu||0)*(+l.qte||0):(+l.qte||0)>0?+l.qte:1);const W=w.reduce((s,x)=>s+x,0)||1;lines.forEach((l,i)=>{l.pu=(+l.qte||0)>0?Math.round(C.total*w[i]/W/(+l.qte)*100)/100:0;});absorb(lines,C.total);
      D.lignes=L;upd({dpgf:D});render();say('Prix de vente réparti sur '+lines.length+' lignes (au prorata de l\'existant, sinon des quantités) — ajuste ligne par ligne');return true;}
    case 'dpround':{if(!canEdit)return true;const D=Object.assign({},a.dpgf||{});const C=calcAffaire(a);const L=(D.lignes||[]).map(l=>Object.assign({},l));const lines=L.filter(l=>!l.section&&(+l.qte||0)>0);lines.forEach(l=>{l.pu=Math.round(+l.pu||0);});if(C.total)absorb(lines,C.total);D.lignes=L;upd({dpgf:D});render();return true;}
    case 'dpsrc':{if(!canEdit)return true;const D=Object.assign({},a.dpgf||{});D.map=Object.assign({},D.map||{});const m=Object.assign({},D.map[arg]||{});m.srcs=(m.srcs||[]).concat([{key:'',pct:''}]);D.map[arg]=m;upd({dpgf:D});render();return true;}
    case 'dpsrcrm':{if(!canEdit)return true;const D=Object.assign({},a.dpgf||{});D.map=Object.assign({},D.map||{});const m=Object.assign({},D.map[arg]||{});m.srcs=(m.srcs||[]).filter((x,j)=>j!==+arg2);D.map[arg]=m;upd({dpgf:D});render();return true;}
    case 'dpapply':{if(!canEdit)return true;const T=dpgfTranslate(a);if(!T.S.C.v2)return true;const D=Object.assign({},a.dpgf||{});const L=(D.lignes||[]).map(l=>Object.assign({},l));T.perLine.forEach(x=>{if(x.srcs.length||x.ml)L[x.i].pu=Math.round(x.pu*100)/100;});const lines=L.filter(l=>!l.section&&(+l.qte||0)>0);absorb(lines,T.vente);D.lignes=L;upd({dpgf:D});render();say('PU écrits sur '+T.perLine.filter(x=>x.srcs.length||x.ml).length+' lignes — total = prix de vente');return true;}
    case 'dpxlsx':{dpgfXlsx(a).catch(e=>{console.warn(e);say('Export impossible : '+(e.message||e));});return true;}
    case 'dpcsv':{try{const blob=new Blob([dpgfCSV(a)],{type:'text/csv;charset=utf-8'});const u=URL.createObjectURL(blob);const l=document.createElement('a');l.href=u;l.download='DPGF_'+String(a.num).replace(/[^A-Za-z0-9-]/g,'_')+'.csv';document.body.appendChild(l);l.click();setTimeout(()=>{URL.revokeObjectURL(u);l.remove();},2000);say('⬇ DPGF exportée (CSV Excel)');}catch(e){console.warn(e);}return true;}
    case 'dpprint':{const L=((a.dpgf||{}).lignes||[]);const w=window.open('','_blank');if(!w)return true;w.document.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>DPGF ${esc(a.num)}</title><style>body{font:11pt Calibri,Arial,sans-serif;margin:20px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #999;padding:4px 6px;font-size:10pt}th{background:#eee}td.n{text-align:right}tr.s td{background:#f3f3f3;font-weight:700}</style></head><body><h2>DPGF — ${esc(a.num)} · ${esc(a.nom||'')} · ${esc(a.client||'')}</h2><table><tr><th>N°</th><th>Désignation</th><th>U</th><th>Qté</th><th>PU HT</th><th>Total HT</th></tr>${L.map(l=>l.section?`<tr class="s"><td>${esc(l.n||'')}</td><td colspan="5">${esc(l.des)}</td></tr>`:`<tr><td>${esc(l.n||'')}</td><td>${esc(l.des)}</td><td>${esc(l.u||'')}</td><td class="n">${nb(l.qte,2)}</td><td class="n">${nb(l.pu,2)}</td><td class="n">${nb((+l.pu||0)*(+l.qte||0),2)}</td></tr>`).join('')}<tr><td colspan="5"><b>Total HT</b></td><td class="n"><b>${nb(L.filter(l=>!l.section).reduce((s,l)=>s+(+l.pu||0)*(+l.qte||0),0),2)}</b></td></tr></table></body></html>`);w.document.close();setTimeout(()=>{try{w.print();}catch(e){}},300);return true;}
    case 'opiece':{if(!canEdit)return true;const O=Object.assign({},a.offre||{});O.pieces=Object.assign({},O.pieces||{});O.pieces[arg]=!O.pieces[arg];upd({offre:O});render();return true;}
    case 'oremise':{if(!canEdit)return true;const C=calcAffaire(a);if(!confirm('Marquer l\'offre remise'+(C.total?' à '+eur(C.total):'')+' ? La date est tracée, le montant du devis se remplit.'))return true;const O=Object.assign({},a.offre||{},{remiseAt:new Date().toISOString(),montant:C.total||a.montant||null,version:a.chiffrageV||1});const p={offre:O};if(!a.montant&&C.total)p.montant=Math.round(C.total);if(a.etat==='preconsult')p.etat='devis';upd(p);render();say('📤 Offre remise — le reporting est à jour');return true;}
    case 'ogagne':{if(!canEdit)return true;if(!confirm('Affaire gagnée : elle passe « à débuter » (dossier en cours) ?'))return true;const O=Object.assign({},a.offre||{},{gagneAt:new Date().toISOString()});upd({offre:O,etat:'a_debuter'});AS().seg='cours';render();say('🏆 Gagnée — dossier en cours : lie le chantier, prépare la facturation');return true;}
    case 'operdu':{if(!canEdit)return true;const motif=prompt('Perdue — motif (prix, technique, délai, autre) :','prix');if(motif===null)return true;const pg=prompt('Prix du gagnant si connu (€ HT, vide sinon) :','');const O=Object.assign({},a.offre||{},{perduAt:new Date().toISOString(),motif:String(motif).trim(),prixGagnant:pg&&+String(pg).replace(/\s/g,'').replace(',','.')||null});upd({offre:O,etat:'perdu'});AS().seg='fin';render();say('Perdue — gardée dans le Reporting');return true;}
  }
  return false;}
export function commerceInput(el,ctx){const d=el.dataset;const a=AS().cur?affGet(AS().cur):null;if(!a)return false;const num=v=>v===''?null:(isFinite(+v)?+v:v);const render=()=>{if(ctx.render)ctx.render();};
  if(d.afcs!==undefined){if(d.afcs==='moa'||d.afcs==='moe'||d.afcs==='dateReponse'){affSet(a.num,{[d.afcs]:el.value});}else{const c=Object.assign({},a.consult||{});c[d.afcs]=el.value;affSet(a.num,{consult:c});}if(['dateReponse','questions','visite'].includes(d.afcs))render();return true;}
  if(d.afq!==undefined){const q=Object.assign({rows:[]},a.quantites||{});q[d.afq]=num(el.value);affSet(a.num,{quantites:q});return true;}
  if(d.afqr!==undefined){const [i,k]=d.afqr.split('|');const q=Object.assign({rows:[]},a.quantites||{});q.rows=(q.rows||[]).map((r,j)=>j===+i?Object.assign({},r,{[k]:k==='dn'?+el.value:(el.type==='checkbox'?el.checked:num(el.value))}):r);affSet(a.num,{quantites:q});render();return true;}
  if(d.afm!==undefined){const M=Object.assign({},a.memoire||{});const i=AS().msec||0;M.sections=(M.sections||[]).map((s,j)=>j===i?Object.assign({},s,{[d.afm]:el.value}):s);affSet(a.num,{memoire:M});if(d.afm!=='texte')render();return true;}
  if(d.afdm!==undefined){const [i,j,k]=d.afdm.split('|');const D=Object.assign({},a.dpgf||{});D.map=Object.assign({},D.map||{});const m=Object.assign({},D.map[i]||{});if(k==='ml'){m.ml=el.checked;}else{m.srcs=(m.srcs||[]).map((s,x)=>x===+j?Object.assign({},s,{[k]:el.value}):s);}D.map[i]=m;affSet(a.num,{dpgf:D});render();return true;}
  if(d.afdp!==undefined){const D=Object.assign({},a.dpgf||{});D.lignes=(D.lignes||[]).map((l,j)=>j===+d.afdp?Object.assign({},l,{pu:num(el.value)||0}):l);affSet(a.num,{dpgf:D});render();return true;}
  return false;}
/* fichier DPGF déposé (appelé par la délégation « change » de l'espace) */
export async function dpgfFile(num,file,ctx){const a=affGet(num);if(!a||!ctx.canEdit||!file)return;const say=t=>A&&A.toast&&A.toast(t);let rows=[];const isX=/\.xlsx$/i.test(file.name);
  try{if(isX)rows=await xlsxRows(file,{grid:true});else rows=pasteRows(await file.text());}catch(e){console.warn(e);say('Fichier illisible ('+(e.message||e)+') : colle les lignes depuis Excel');return;}
  const meta={};const L=dpgfFromRows(rows,meta);if(!L.length){say('Aucune ligne reconnue : il faut une ligne d\'en-tête avec Désignation et Quantité');return;}
  let kept=false;if(isX){try{kept=await A.kv.set('trace:dpgf:'+num,file);}catch(e){kept=false;}} /* le fichier du client est gardé sur l'appareil pour y réécrire les PU (export) */
  affSet(num,{dpgf:{lignes:L,src:isX?'Excel du client':'fichier',fichier:file.name,at:new Date().toISOString(),hdrRow:meta.hdrRow,cols:meta.cols,sheet:meta.sheet,kept,map:((a.dpgf||{}).map)||{}}});say('DPGF lue : '+L.filter(l=>!l.section).length+' lignes'+(L.some(l=>l.section)?' · '+L.filter(l=>l.section).length+' chapitres':'')+(kept?' · fichier gardé pour l\'export':''));if(ctx.render)ctx.render();}
/* ── 13/10 : TRADUIRE NOTRE PRIX DANS LA DPGF — chaque ligne du bordereau reçoit des sources (poste d'une zone, panier libre) ; le reste (postes non affectés) se ventile
   au ml sur les lignes cochées « au ml » (au prorata de leur quantité) ; « Appliquer » écrit les PU ; l'export réécrit les PU dans le fichier Excel du client. ── */
const DPSRC_ETUDES=a=>((a.chiffrage||{}).etudes)||[];
export function dpgfSources(a){const C=calcAffaire(a);if(!C.v2)return {C,opts:[],amount:()=>0};const E=C.etudes;const opts=[];
  E.forEach((e,ei)=>{Object.keys(e.r.postes).forEach(k=>{const p=e.r.postes[k];if(!p.achat)return;const P=C.postes.find(x=>x.k===k);opts.push({key:'p|'+ei+'|'+k,label:(e.z.nom||'Zone '+(ei+1))+' › '+(P?P.label:k),vente:p.achat/(C.coef||1)});});
    ((e.r.detail||{}).paniers||{rows:[]}).rows.forEach((pn,pi)=>{opts.push({key:'b|'+ei+'|'+pi,label:(e.z.nom||'Zone '+(ei+1))+' › panier « '+(pn.nom||'')+' »',vente:pn.total/(C.coef||1)});});});
  const amount=key=>{const o=opts.find(x=>x.key===key);return o?o.vente:0;};return {C,opts,amount};}
export function dpgfTranslate(a){const D=a.dpgf||{};const L=D.lignes||[];const S=dpgfSources(a);const map=D.map||{};const lines=L.map((l,i)=>({l,i}));const used={};let assigned=0;
  const perLine=lines.map(({l,i})=>{if(l.section)return null;const srcs=map[i]&&map[i].srcs||[];let amt=0;srcs.forEach(s=>{const v=S.amount(s.key)*(s.pct===undefined||s.pct===''?1:(+s.pct||0)/100);amt+=v;used[s.key]=(used[s.key]||0)+(s.pct===undefined||s.pct===''?1:(+s.pct||0)/100);});assigned+=amt;return {i,amt,ml:!!(map[i]&&map[i].ml),srcs};}).filter(Boolean);
  const vente=S.C.total||0;const reste=Math.max(0,vente-assigned);const mlLines=perLine.filter(x=>x.ml);const W=mlLines.reduce((s,x)=>s+(+L[x.i].qte||0),0)||0;
  perLine.forEach(x=>{x.resteMl=x.ml&&W?reste*(+L[x.i].qte||0)/W:0;x.total=x.amt+x.resteMl;x.pu=(+L[x.i].qte||0)?x.total/(+L[x.i].qte):0;});
  const over=Object.keys(used).filter(k=>used[k]>1.0001);const unassigned=S.opts.filter(o=>!used[o.key]);return {S,perLine,assigned,reste,vente,mlLines:mlLines.length,W,over,unassigned};}
export function dpgfMapHTML(a,canEdit){const D=a.dpgf||{};const L=D.lignes||[];if(!L.length)return '';const T=dpgfTranslate(a);if(!T.S.C.v2)return `<div class="card"><h3>Traduire le prix dans la DPGF</h3><div class="eq-s">Avec le chiffrage complet (zones, postes, paniers) chaque ligne du bordereau se relie à un poste d'une zone ; en attendant : « Répartir » puis ajustement ligne par ligne.</div></div>`;const ro=!canEdit;const map=D.map||{};
  const optHTML=sel=>`<option value="">— choisir une source —</option>${T.S.opts.map(o=>`<option value="${esc(o.key)}"${o.key===sel?' selected':''}>${esc(o.label)} · ${eur(o.vente)}</option>`).join('')}`;
  const rows=L.map((l,i)=>{if(l.section)return `<tr class="sub"><td colspan="5">${esc(l.n||'')} ${esc(l.des)}</td></tr>`;const x=T.perLine.find(p=>p.i===i);const srcs=(map[i]&&map[i].srcs)||[];
    return `<tr><td><b>${esc(l.n||'')}</b> ${esc(l.des)}<div class="dim" style="font-size:11px">${nb(l.qte,2)} ${esc(l.u||'')}${l.pu?' · PU actuel '+nb(l.pu,2)+' €':''}</div></td><td>${srcs.map((s,j)=>`<div class="cm-dpsrc"><select class="f" data-afdm="${i}|${j}|key" ${ro?'disabled':''}>${optHTML(s.key)}</select><input class="f af-n" type="number" min="0" max="100" step="1" data-afdm="${i}|${j}|pct" value="${esc(s.pct===undefined?'':s.pct)}" placeholder="100 %" title="Part du poste sur cette ligne (%)" ${ro?'disabled':''}>${ro?'':`<button class="btn sm ch-rm" data-act="af" data-v="dpsrcrm|${i}|${j}">✕</button>`}</div>`).join('')}${ro?'':`<button class="btn sm" data-act="af" data-v="dpsrc|${i}">＋ source</button>`}</td><td><label class="ch-sw${x&&x.ml?' on':''}" title="Reçoit sa part du reste (postes non affectés), au prorata de sa quantité"><input type="checkbox" data-afdm="${i}|ml|ml" ${x&&x.ml?'checked':''} ${ro?'disabled':''}><i></i><span>au ml</span></label></td><td class="num">${x?eur(x.amt)+(x.resteMl?' <span class="dim">+ '+eur(x.resteMl)+'</span>':''):''}</td><td class="num"><b>${x&&x.pu?nb(x.pu,2):'—'}</b></td></tr>`;}).join('');
  return `<div class="card"><h3>Traduire notre prix dans la DPGF <span class="hint">· tel panier de telle zone = cette ligne ; le reste, au ml</span></h3>
    <div class="ac-stats" style="margin-bottom:8px"><div class="ac-stat or"><b>${eur(T.vente)}</b><small>prix de vente HT à traduire</small></div><div class="ac-stat ${T.assigned>T.vente+1?'bad':''}"><b>${eur(T.assigned)}</b><small>affecté à des lignes</small></div><div class="ac-stat ${T.reste>1&&!T.mlLines?'warn':''}"><b>${eur(T.reste)}</b><small>reste, ventilé au ml sur ${T.mlLines} ligne${T.mlLines>1?'s':''}${T.W?' ('+nb(T.W)+' ml)':''}</small></div><div class="ac-stat ${T.unassigned.length?'warn':'ok'}"><b>${T.unassigned.length}</b><small>poste${T.unassigned.length>1?'s':''} non affecté${T.unassigned.length>1?'s':''} (→ au ml)</small></div></div>
    ${T.over.length?`<div class="warnbox" style="margin-bottom:6px">⚠ Affecté à plus de 100 % : ${T.over.map(k=>esc((T.S.opts.find(o=>o.key===k)||{}).label||k)).join(' · ')}</div>`:''}
    <div style="overflow:auto"><table class="rc af-tab cm-dpgf cm-dpmap"><tr><th>Ligne du bordereau</th><th>Sources (zone › poste ou panier · part)</th><th>Reste</th><th>Montant</th><th>PU proposé</th></tr>${rows}</table></div>
    ${canEdit?`<div class="eq-acts" style="margin-top:8px"><button class="btn primary" data-act="af" data-v="dpapply|">→ Appliquer ces PU au bordereau</button>${D.kept?`<button class="btn" data-act="af" data-v="dpxlsx|">⬇ Excel du client rempli (.xlsx)</button>`:'<span class="hint">Export dans le fichier du client : importe le .xlsx (pas un collage) pour y réécrire les PU.</span>'}</div>`:''}
    ${T.unassigned.length?`<details style="margin-top:6px"><summary class="dim" style="cursor:pointer;font-size:12px;min-height:30px;display:flex;align-items:center">Postes non affectés · ${T.unassigned.length} · ${eur(T.unassigned.reduce((s,o)=>s+o.vente,0))}</summary><div class="dim" style="font-size:12px">${T.unassigned.map(o=>esc(o.label)+' · '+eur(o.vente)).join('<br>')}</div></details>`:''}
    <div class="hint" style="margin-top:6px">Une source peut être partagée entre plusieurs lignes (part en %). Les lignes « au ml » se partagent le reste au prorata de leur quantité — divisé par le ml, comme sur le classeur. « Appliquer » écrit les PU (le total tombe sur le prix de vente, au centime) ; tu peux ensuite retoucher ligne par ligne.</div></div>`;}
export async function dpgfXlsx(a){const D=a.dpgf||{};const say=t=>A&&A.toast&&A.toast(t);let file=null;try{file=await A.kv.get('trace:dpgf:'+a.num);}catch(e){}if(!file){say('Le fichier Excel du client n\'est pas sur cet appareil : réimporte-le');return;}
  const ze=zipEntriesX,inf=inflateX;const buf=await file.arrayBuffer();const Z=await ze(buf);const sheet=D.sheet||Object.keys(Z).find(x=>x==='xl/worksheets/sheet1.xml')||Object.keys(Z).filter(x=>/^xl\/worksheets\/sheet\d+\.xml$/.test(x)).sort()[0];if(!sheet||!Z[sheet]){say('Feuille introuvable dans le fichier');return;}
  let xml=await inf(Z[sheet]);const cols=D.cols||{};let iP=cols.pu;let iT=cols.tot;const vals={};const L=D.lignes||[];
  if(iP===undefined||iP<0){iP=Math.max(cols.qte||0,cols.des||0,cols.u||0)+1;if(D.hdrRow)vals[colName(iP+1)+D.hdrRow]='PU HT (SCR)';} /* pas de colonne PU dans le fichier : on l'ajoute après la quantité */
  L.forEach(l=>{if(l.section||!l.row)return;vals[colName(iP+1)+l.row]=Math.round((+l.pu||0)*100)/100;if(iT!==undefined&&iT>=0)vals[colName(iT+1)+l.row]=Math.round((+l.pu||0)*(+l.qte||0)*100)/100;});
  xml=setCellsXml(xml,vals);const rep={[sheet]:xml};if(Z['xl/workbook.xml']){let wx=await inf(Z['xl/workbook.xml']);if(/<calcPr\b/.test(wx)){if(!/fullCalcOnLoad/.test(wx))wx=wx.replace(/<calcPr\b/,'<calcPr fullCalcOnLoad="1"');}else wx=wx.replace('</workbook>','<calcPr fullCalcOnLoad="1"/></workbook>');rep['xl/workbook.xml']=wx;} /* Excel recalcule les totaux à l'ouverture */
  const out=await rezip(Z,rep);const blob=new Blob([out],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});const u=URL.createObjectURL(blob);const el=document.createElement('a');el.href=u;el.download=String(D.fichier||'DPGF.xlsx').replace(/\.xlsx$/i,'')+'_SCR.xlsx';document.body.appendChild(el);el.click();setTimeout(()=>{URL.revokeObjectURL(u);el.remove();},2000);say('⬇ DPGF du client remplie : '+L.filter(l=>!l.section).length+' PU écrits, mise en forme conservée');}
